tool_calls.command:
# Create a proper C fuzzing harness for curl using libcurl
cat > /workspace/curl_fuzz_harness.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

static size_t write_cb(void *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)ptr; (void)userdata;
    return size * nmemb;
}

int main(int argc, char **argv) {
    // AFL++ persistent mode with persistent loop
    // Read fuzzed input from stdin or file (argv[1])
    char buf[4096];
    size_t len;

#ifdef __AFL_LOOP
    while (__AFL_LOOP(1000)) {
#endif
        if (argc > 1) {
            FILE *f = fopen(argv[1], "rb");
            if (!f) return 0;
            len = fread(buf, 1, sizeof(buf) - 1, f);
            fclose(f);
        } else {
            len = fread(buf, 1, sizeof(buf) - 1, stdin);
        }
        buf[len] = '\0';

        // Trim whitespace
        char *end = buf + len - 1;
        while (end > buf && (*end == '\n' || *end == '\r' || *end == ' ')) *end-- = '\0';

        if (strlen(buf) == 0) {
#ifdef __AFL_LOOP
            continue;
#else
            return 0;
#endif
        }

        CURL *curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, buf);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
            curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
            curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 2L);
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, 3L);
            curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 0L);
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
            curl_easy_setopt(curl, CURLOPT_VERBOSE, 0L);
            curl_easy_setopt(curl, CURLOPT_NOPROGRESS, 1L);
            curl_easy_setopt(curl, CURLOPT_PROTOCOLS,
                CURLPROTO_HTTP | CURLPROTO_HTTPS | CURLPROTO_FTP | CURLPROTO_FILE);
            curl_easy_perform(curl);
            curl_easy_cleanup(curl);
        }
#ifdef __AFL_LOOP
    }
#endif
    return 0;
}
EOF

echo "C harness created"

