cd /workspace/curl && afl-cc -I/workspace/curl/include -o /workspace/curl_fuzz_harness /workspace/curl_fuzz_harness.c -L/workspace/curl/lib/.libs -lcurl -lssl -lcrypto -lz -lnghttp2 -lpsl -lzstd -lbrotlidec -lbrotlicommon -lpthread -lidn2 -lldap -llber 2>&1 | grep -v warning

echo "Harness recompiled"
echo "file:///etc/hostname" | /workspace/curl_fuzz_harness
echo "Exit code: $?"

